<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {api,upload} from '../api'
import {desk,inr,label} from '../stores/desk'
import type {Case,Evidence} from '../types'
import StatusBadge from '../components/StatusBadge.vue'
const props=defineProps<{id:string}>()
const c=ref<Case|null>(null),tab=ref('Overview'),evidence=ref<Evidence[]>([]),audit=ref<any[]>([])
const kind=ref('bank'),replaces=ref(''),progress=ref(0),uploading=ref(false),review=ref('approve'),comments=ref(''),selectedEvidence=ref(''),requestNotes=ref<Record<string,string>>({})
const tabs=['Overview','Documents','Evidence','Analysis','CAM','Human review','Audit history']
const currentCam=computed(()=>c.value?.cam_versions?.find(v=>v.revision===c.value?.revision))
const cam=computed(()=>currentCam.value?.data)
const latestOld=computed(()=>c.value?.cam_versions?.at(-1))
const checkpoints=computed(()=>c.value?.agent_runs?.filter(r=>r.revision===c.value?.revision)||[])
const financial=computed(()=>cam.value?.financial_analysis||checkpoints.value.find(r=>r.node==='cashflow')?.data.result)
const checks=computed(()=>cam.value?.policy_checks||checkpoints.value.find(r=>r.node==='policy')?.data.result||[])
const approvable=computed(()=>!!cam.value&&c.value?.analyzed_revision===c.value?.revision&&checks.value.every((p:any)=>p.result==='pass'))
const activeDocs=computed(()=>c.value?.documents?.filter(d=>d.status!=='superseded')||[])
const openRequests=computed(()=>c.value?.evidence_requests?.filter(r=>r.status==='open'&&(r.data.source==='reviewer'||r.revision===c.value?.revision))||[])
async function load(){c.value=await api('/applications/'+props.id);desk.selected=c.value;const [ev,au]=await Promise.all([api('/applications/'+props.id+'/evidence?limit=500'),api('/applications/'+props.id+'/audit?limit=500')]);evidence.value=ev.items;audit.value=au.items}
async function action(fn:()=>Promise<unknown>){desk.busy=true;desk.error='';try{await fn();await load()}catch(e){desk.error=(e as Error).message}finally{desk.busy=false}}
let timer:ReturnType<typeof setInterval>|undefined
async function analyze(){timer=setInterval(()=>{api('/applications/'+props.id+'/runs').then(r=>{if(c.value){c.value.status=r.status;c.value.agent_runs=r.items}}).catch(()=>{})},1500);try{await action(async()=>{const r=await api('/applications/'+props.id+'/runs',{});if(r.status==='failed')throw new Error('Analysis failed at '+r.node+'. Inspect pipeline status, then retry.');return r})}finally{clearInterval(timer);await load()}}
onUnmounted(()=>clearInterval(timer))
async function filesChanged(e:Event){const input=e.target as HTMLInputElement;const files=Array.from(input.files||[]);uploading.value=true;desk.error='';try{for(const file of files){progress.value=0;await upload(props.id,file,kind.value,replaces.value,v=>progress.value=v)}replaces.value='';await load()}catch(e){desk.error=(e as Error).message;await load()}finally{uploading.value=false;input.value=''}}
async function decide(){if(!c.value)return;await action(()=>api('/applications/'+props.id+'/review',{decision:review.value,revision:c.value!.revision,comments:comments.value}));comments.value=''}
function showEvidence(id:string){selectedEvidence.value=id;tab.value='Evidence'}
function print(){window.print()}
onMounted(()=>action(load))
</script>
<template><div v-if="c" class="workspace"><div class="page-heading"><div><div class="eyebrow">CASE {{c.id.slice(0,8).toUpperCase()}} / REVISION {{c.revision}}</div><h1>{{c.data.business}}</h1><p>{{c.data.applicant}} <span class="dot">·</span> {{c.data.purpose}}</p></div><div class="heading-actions"><StatusBadge :value="c.status"/><button class="primary" @click="analyze" :disabled="desk.busy||uploading||['approved','rejected','processing'].includes(c.status)">{{desk.busy?'Processing…':'Run analysis'}}</button></div></div>
<div class="case-summary"><div><small>REQUESTED LOAN</small><strong>{{inr(c.data.requested_amount)}}</strong></div><div><small>TENURE</small><strong>{{c.data.tenure_months}} months</strong></div><div><small>DOCUMENTS</small><strong>{{activeDocs.length}} uploaded</strong></div><div><small>CURRENT CAM</small><strong>{{cam?'Revision '+c.revision:'Awaiting analysis'}}</strong></div></div>
<div class="tabs"><button v-for="t in tabs" :key="t" :class="{active:tab===t}" @click="tab=t">{{t}}</button></div>
<section v-if="tab==='Overview'" class="two-columns"><div class="panel"><div class="section-title"><h2>Analysis pipeline</h2><span class="subtle">Sequential · checkpointed</span></div><div v-for="node in ['documents','reconciliation','cashflow','fraud','risk','policy','structure','cam']" class="pipeline-row"><span class="node-icon">{{checkpoints.find(r=>r.node===node)?.status==='complete'?'✓':'○'}}</span><div><strong>{{label(node)}}</strong><small>{{checkpoints.find(r=>r.node===node)?.data.error||'Version 1.0 · deterministic rules & evidence'}}</small></div><StatusBadge :value="checkpoints.find(r=>r.node===node)?.status||'pending'"/></div></div><div><div class="panel"><h2>Review readiness</h2><p v-if="!cam">Add documents and run analysis to build the case.</p><template v-else><div class="readiness" :class="{ready:approvable}">{{approvable?'Ready for human review':'Evidence or policy review required'}}</div><p>{{checks.filter((p:any)=>p.result==='pass').length}} of {{checks.length}} checks passing. Human approval is always required.</p></template><h3>Evidence requests</h3><p v-if="!openRequests.length" class="subtle">No current evidence requests.</p><div v-for="r in openRequests" class="gap">{{r.data.message}}</div></div><div class="notice">All proposals are synthetic. Uploaded classifications and source values require reviewer verification.</div></div></section>
<section v-if="tab==='Documents'" class="panel"><div class="section-title"><h2>Document inventory</h2><span class="subtle">Private storage · 10 MiB / file · 50 PDF pages</span></div><p>Upload one synthetic document for each type. Corrections must explicitly replace the previous document.</p><div class="upload-controls"><label>Document type<select v-model="kind"><option v-for="k in ['bank','gst','itr','financial','kyc','bureau']">{{k}}</option></select></label><label>Replacement (optional)<select v-model="replaces"><option value="">New evidence</option><option v-for="d in activeDocs.filter(d=>d.kind===kind)" :value="d.id">Replace {{d.name}}</option></select></label><label class="upload-button">{{uploading?'Uploading… '+progress+'%':'＋ Choose PDF / JSON'}}<input type="file" accept=".pdf,.json" multiple @change="filesChanged" :disabled="uploading||desk.busy||['approved','rejected'].includes(c.status)"></label></div><progress v-if="uploading" :value="progress" max="100"></progress><div class="table-wrap"><table><thead><tr><th>Document</th><th>Type</th><th>Validation</th><th>Pages / details</th></tr></thead><tbody><tr v-for="d in c.documents"><td>{{d.name}}<small>{{d.sha256.slice(0,16)}}…</small></td><td class="uppercase">{{d.kind}}</td><td><StatusBadge :value="d.status"/></td><td>{{d.data.error|| (d.data.pages_present?d.data.pages_present.length+' / '+d.data.expected_pages:'Pending analysis')}}</td></tr><tr v-if="!c.documents?.length"><td colspan="4" class="empty">No documents yet. Add the five required evidence types.</td></tr></tbody></table></div><div class="notice">Supported: supplied synthetic JSON schema or labeled PDF template. General bank PDFs are flagged for manual mapping. Scans use local Tesseract OCR.</div></section>
<section v-if="tab==='Evidence'" class="panel"><div class="section-title"><h2>Evidence explorer</h2><button v-if="selectedEvidence" @click="selectedEvidence=''">Show all fields</button></div><p>Extracted facts retain their source page and text. Showing up to 500 records per case.</p><div class="table-wrap"><table><thead><tr><th>Field / reference</th><th>Normalized value</th><th>Source</th><th>Supporting text</th></tr></thead><tbody><tr v-for="e in evidence.filter(e=>!selectedEvidence||e.evidence_id===selectedEvidence)" :key="e.evidence_id" :class="{muted:e.superseded}"><td><strong>{{e.name||e.transaction_id}}</strong><small>{{e.evidence_id.slice(0,8)}} · extracted fact{{e.superseded?' · superseded':''}}</small></td><td>{{e.value??inr(e.amount)}}<small>{{e.date}} {{e.category}}</small></td><td>{{e.document_name}}<small>Page {{e.page}}</small></td><td class="source-text">{{e.source_text}}</td></tr><tr v-if="!evidence.length"><td colspan="4" class="empty">Extract documents to see cited evidence.</td></tr></tbody></table></div></section>
<section v-if="tab==='Analysis'"><div class="metric-grid" v-if="financial"><div class="panel"><small>OPERATING CASH / MONTH</small><strong class="metric">{{inr(financial.monthly_operating_cash)}}</strong><small>Calculated · reconciled receipts less expenses</small></div><div class="panel"><small>PROPOSED EMI</small><strong class="metric">{{inr(financial.proposed_emi)}}</strong><small>{{financial.annual_rate_percent}}% nominal annual · reducing balance</small></div><div class="panel"><small>DSCR</small><strong class="metric">{{financial.dscr?.toFixed(2)??'Unknown'}}</strong><small>Annual operating cash / total debt service</small></div></div><div class="panel"><h2>Policy & eligibility</h2><div class="table-wrap"><table><thead><tr><th>Rule</th><th>Result</th><th>Inputs & rationale</th></tr></thead><tbody><tr v-for="p in checks"><td><strong>{{p.rule_id}}</strong><small>{{p.rule_version}}</small></td><td><StatusBadge :value="p.result"/></td><td>{{p.reason}}<small>{{JSON.stringify(p.inputs)}}</small></td></tr></tbody></table></div><p v-if="!checks.length" class="empty">Run analysis to evaluate configured demo policies.</p></div><div class="panel" v-if="financial"><h2>Monthly bank activity</h2><div class="table-wrap"><table><thead><tr><th>Month</th><th>Gross credits</th><th>Operating receipts</th><th>Operating expenses</th><th>Debt paid</th></tr></thead><tbody><tr v-for="(row,month) in financial.monthly"><td>{{month}}</td><td>{{inr(row.credits)}}</td><td>{{inr(row.operating_credits)}}</td><td>{{inr(row.operating_debits)}}</td><td>{{inr(row.debt)}}</td></tr></tbody></table></div><details><summary>Formulas, inputs & assumptions</summary><pre>{{JSON.stringify({formulas:financial.formulas,inputs:financial.inputs,assumptions:financial.assumptions},null,2)}}</pre></details></div><div class="panel"><h2>Reconciliation & investigation</h2><template v-for="node in checkpoints.filter(r=>['reconciliation','fraud'].includes(r.node))"><div v-for="finding in node.data.result" class="finding"><StatusBadge :value="finding.result||finding.classification"/><strong>{{finding.comparison||finding.kind}}</strong><p>{{finding.reason||finding.message}}</p><div class="citations"><button v-for="id in finding.evidence_ids.slice(0,12)" @click="showEvidence(id)">↗ {{id.slice(0,8)}}</button><small v-if="finding.evidence_ids.length>12">+ {{finding.evidence_ids.length-12}} more in Evidence</small></div></div></template></div></section>
<section v-if="tab==='CAM'"><div class="section-title"><div><h2>Credit Appraisal Memo</h2><p>Current revision only. Previous versions remain in the case history.</p></div><button @click="print" :disabled="!cam">Print / save PDF</button></div><div class="panel cam-report" v-if="cam"><div class="eyebrow">SYNTHETIC DEMO / {{cam.policy_version}}</div><h1>{{cam.title}}</h1><p>{{c.data.business}} · Revision {{c.revision}} · {{new Date(cam.generated_at).toLocaleString()}}</p><StatusBadge :value="cam.outcome"/><h2>Applicant & loan</h2><p>{{c.data.applicant}} requests {{inr(c.data.requested_amount)}} over {{c.data.tenure_months}} months for {{c.data.purpose}}. Source: applicant-entered metadata.</p><h2>Repayment capacity</h2><p>Operating cash: {{inr(financial?.monthly_operating_cash)}} / month. Existing debt: {{inr(financial?.existing_monthly_debt)}} / month. Proposed EMI: {{inr(financial?.proposed_emi)}}. DSCR: {{financial?.dscr?.toFixed(2)??'insufficient evidence'}}.</p><h2>Proposed terms</h2><p>{{cam.proposal.rationale}} Capacity limit: {{inr(cam.proposal.capacity_limit)}}. Interest: {{cam.proposal.nominal_annual_rate_percent}}% nominal annual, monthly reducing balance.</p><h2>Policy outcomes</h2><div v-for="p in cam.policy_checks" class="memo-rule"><strong>{{p.rule_id}}</strong><StatusBadge :value="p.result"/><span>{{p.reason}}</span></div><h2>Reconciliation</h2><p v-for="r in cam.reconciliation">{{r.comparison}}: {{r.result}}. {{r.reason}}</p><h2>Investigation & risk</h2><p v-if="!cam.investigation_flags.length">No configured transaction flags detected; this is not an assurance of absence of fraud.</p><p v-for="f in cam.investigation_flags">{{f.kind}} — {{f.message}} <span v-for="id in f.evidence_ids" class="inline-ref">[{{id.slice(0,8)}}]</span></p><p>Leverage: {{cam.risk.leverage}}.</p><h2>Evidence gaps & limitations</h2><p v-for="gap in cam.evidence_gaps">{{gap}}</p><p v-for="lim in cam.limitations">{{lim}}</p><details open><summary>Calculation methods & assumptions</summary><pre>{{JSON.stringify({formulas:financial?.formulas,inputs:financial?.inputs,assumptions:financial?.assumptions},null,2)}}</pre></details><h2>Model explanation · {{cam.model_explanation.mode}}</h2><p>{{cam.model_explanation.text}}</p><h2>Reviewer clarifications</h2><p v-for="r in cam.clarifications">{{r.message}} · {{r.status}} · {{r.resolution||'Awaiting response'}}</p><h2>Source evidence</h2><p>All underlying fields and transactions supporting this memo:</p><div v-for="e in evidence.filter(e=>cam.evidence_ids.includes(e.evidence_id))" class="memo-evidence"><button @click="showEvidence(e.evidence_id)">[{{e.evidence_id.slice(0,8)}}] {{e.name||e.transaction_id}}</button> {{e.document_name}}, p.{{e.page}} · {{e.value??inr(e.amount)}}<small>{{e.source_text}}</small></div><h2>Reviewer history</h2><p v-for="d in c.decisions">{{d.created_at}} · {{d.reviewer_id}} · {{d.data.decision}} · {{d.data.comments}}</p><p v-if="!c.decisions?.length">No decision recorded. Human approval required.</p></div><div v-else class="panel empty">No current memo. {{latestOld?'An older memo exists but is stale. Re-run analysis after updating evidence.':'Run analysis after uploading documents.'}}</div><details v-if="c.cam_versions?.length"><summary>Memo version history ({{c.cam_versions.length}})</summary><p v-for="version in c.cam_versions">Revision {{version.revision}} · {{version.created_at}} · {{version.revision===c.revision?'current':'stale — unavailable for approval'}}</p></details></section>
<section v-if="tab==='Human review'" class="two-columns"><form class="panel" @submit.prevent="decide"><h2>Record a decision</h2><p>Reviewer credentials are required. Approval creates one mock proposal in a database transaction.</p><label>Decision<select v-model="review"><option value="approve">Approve demo proposal</option><option value="reject">Reject application</option><option value="request_evidence">Request additional evidence</option></select></label><label>Reviewer comments<textarea v-model="comments" required minlength="3" maxlength="2000"></textarea></label><div class="notice" v-if="review==='approve'&&!approvable">Approval is blocked until the current CAM and all policy checks pass.</div><button class="primary" :disabled="desk.busy||['approved','rejected'].includes(c.status)||(review==='approve'&&!approvable)">Record {{label(review)}}</button></form><div class="panel"><h2>Decision history</h2><div v-for="d in c.decisions" class="finding"><StatusBadge :value="d.data.decision"/><p>{{d.data.comments}}</p><small>{{d.reviewer_id}} · {{new Date(d.created_at).toLocaleString()}} · revision {{d.revision}}</small></div><p v-if="!c.decisions?.length" class="subtle">No reviewer decisions recorded.</p><h3>Open clarification requests</h3><div v-for="r in openRequests.filter(r=>r.data.source==='reviewer')" class="finding"><p>{{r.data.message}}</p><label>Resolution evidence / rationale<textarea v-model="requestNotes[r.id]" minlength="3" maxlength="2000"></textarea></label><button :disabled="desk.busy||!requestNotes[r.id]||requestNotes[r.id].length<3" @click="action(()=>api('/applications/'+id+'/evidence-requests/'+r.id+'/resolve',{message:requestNotes[r.id]}))">Resolve request</button></div></div></section>
<section v-if="tab==='Audit history'" class="panel"><h2>Append-only case history</h2><div class="table-wrap"><table><thead><tr><th>Timestamp</th><th>Event</th><th>Details</th></tr></thead><tbody><tr v-for="event in audit"><td>{{new Date(event.created_at).toLocaleString()}}</td><td>{{label(event.data.action)}}</td><td><pre>{{JSON.stringify(event.data,null,2)}}</pre></td></tr></tbody></table></div><p class="subtle">Showing up to 500 audit events. API supports pagination.</p></section></div></template>
